class Solution {
public:
    int maxValueAfterReverse(vector<int>& nums) {
        int n = nums.size(), base = 0, gain = 0;
        int largestLow = INT_MIN, smallestHigh = INT_MAX;
        for (int i = 0; i + 1 < n; ++i) {
            int a = nums[i], b = nums[i + 1];
            base += abs(a - b);
            gain = max(gain, abs(nums[0] - b) - abs(a - b));
            gain = max(gain, abs(nums[n - 1] - a) - abs(a - b));
            largestLow = max(largestLow, min(a, b));
            smallestHigh = min(smallestHigh, max(a, b));
        }
        if (n < 2) return 0;
        gain = max(gain, 2 * (largestLow - smallestHigh));
        return base + gain;
    }
};
